package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown when a create-owner request would add an owner to a city that already contains the maximum
 * number of owners (50). Handled by {@link CityAtCapacityExceptionHandler}, which responds 409
 * (Conflict).
 */
public class CityAtCapacityException extends Exception {

    private final String city;

    private final int count;

    public CityAtCapacityException(String city, int count) {
        super("City '" + city + "' already contains " + count + " owners (limit 50)");
        this.city = city;
        this.count = count;
    }

    public String getCity() {
        return this.city;
    }

    public int getCount() {
        return this.count;
    }
}
--- DuplicateIdentityException.java ---
package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown when a create-owner request's derived {@code identityKey} (SHA-256 hex over normalized
 * telephone, lower-cased email and soundex of the last name) exactly matches an existing owner's —
 * i.e. it is a full-key duplicate. Handled by {@link DuplicateIdentityExceptionHandler}, which responds
 * 409 (Conflict).
 */
public class DuplicateIdentityException extends Exception {

    private final String identityKey;

    public DuplicateIdentityException(String identityKey) {
        super("An owner with identity '" + identityKey + "' already exists");
        this.identityKey = identityKey;
    }

    public String getIdentityKey() {
        return this.identityKey;
    }
}
--- DailyOwnerLimitException.java ---
package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown when a create-owner request would exceed the maximum number of owners that may be created
 * in a single day (100), counted by {@code registrationDate}. Handled by
 * {@link DailyOwnerLimitExceptionHandler}, which responds 429 (Too Many Requests).
 */
public class DailyOwnerLimitException extends Exception {

    private final int count;

    public DailyOwnerLimitException(int count) {
        super("Daily owner creation limit reached: " + count + " owners already created today (limit 100)");
        this.count = count;
    }

    public int getCount() {
        return this.count;
    }
}

